function renderLog(){
  const list=$("#log");
  if(!state.log.length){list.replaceChildren(h("li",{},h("p",{class:"empty"},"还没有记录")));return;}
  list.replaceChildren(...state.log.map((d,i)=>h("li",{},h("button",{type:"button",class:"row-btn",onclick:()=>editLog(d)},
    h("span",{class:"n"},i+1),
    h("span",{},h("span",{class:"t"},d.title),d.when?h("span",{class:"when"},d.when):null,
      d.why?h("span",{class:"why"},"为什么："+d.why):null,
      d.note?h("span",{class:"note"},d.note):null)))));
}
function editLog(d){
  if(!need())return;
  openEditor({title:d?"改这个决定":"记一个决定",isNew:!d,
    values:d?{title:d.title||"",why:d.why||"",when:d.when||"",note:d.note||""}:{title:"",why:"",when:"",note:""},
    fields:[{key:"title",label:"决定了什么",type:"textarea",rows:2},{key:"why",label:"为什么",type:"textarea",rows:3},{key:"when",label:"什么时候（可不填）",type:"text",placeholder:"比如：9月25日"},{key:"note",label:"备注",type:"textarea",rows:2}],
    onSave:async(ch,all)=>{
      if(d)return db.doc("log/"+d.id).update({...ch,updatedAt:stamp()});
      if(!(all.title||"").trim())throw {code:"empty"};
      const order=Math.max(0,...state.log.map(x=>x.order||0))+1;
      return db.collection("log").add({title:all.title.trim(),why:(all.why||"").trim(),when:(all.when||"").trim(),note:(all.note||"").trim(),order,updatedAt:stamp()});
    },
    onDelete:d?()=>db.doc("log/"+d.id).delete():null});
}
const armed=new Set();

